<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import ParityDialog from '../components/ParityDialog.vue';
import GameSwitch from '../components/GameSwitch.vue';
import SettingsArtwork from '../components/SettingsArtwork.vue';
import SensitivityHelpWindow from './SensitivityHelpWindow.vue';
export interface GameSettingsPreferences {controlSensitivity:number;sound:boolean;music:boolean;showPlayerFace:boolean;enemyReactionsEnabled:boolean}
const props=withDefaults(defineProps<{locale:string;preferences:GameSettingsPreferences;characterSettingsEnabled?:boolean;saving?:boolean;error?:string}>(),{characterSettingsEnabled:true,saving:false,error:''});
const emit=defineEmits<{close:[];change:[key:keyof GameSettingsPreferences,value:number|boolean]}>();
const help=ref(false),dialog=ref<InstanceType<typeof ParityDialog>>(),draft=ref(props.preferences.controlSensitivity),ru=computed(()=>props.locale==='ru');
watch(()=>props.preferences.controlSensitivity,value=>{draft.value=value;});
const tiles=computed(()=>[{key:'sound' as const,label:ru.value?'Звуки':'Sounds',index:0},{key:'music' as const,label:ru.value?'Музыка':'Music',index:1},...(props.characterSettingsEnabled?[{key:'showPlayerFace' as const,label:ru.value?'Лицо героя':'Hero face',index:2},{key:'enemyReactionsEnabled' as const,label:ru.value?'Лица врагов':'Enemy faces',index:3}]:[])]);
const sensitivity=computed(()=>`×${draft.value.toFixed(Number.isInteger(draft.value)?0:2)}`);
function changeSensitivity(value:number){draft.value=value;emit('change','controlSensitivity',value);}
</script>
<template><ParityDialog ref="dialog" :title="ru?'Настройки':'Settings'" :locale="locale" name="game-settings" variant="settings" :inactive="help" @close="emit('close')"><template #leading><svg class="port-settings-heading-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 3-.6 2.3-1.6.9-2.3-.6-2.5 4.3 1.7 1.7v1.8l-1.7 1.7L5 19.4l2.3-.6 1.6.9.6 2.3h5l.6-2.3 1.6-.9 2.3.6 2.5-4.3-1.7-1.7v-1.8l1.7-1.7L19 5.6l-2.3.6-1.6-.9-.6-2.3z"/><circle cx="12" cy="12.5" r="3.3"/></svg></template><div class="port-settings-body"><section class="port-sensitivity-card"><header><b>{{ru?'Чувствительность':'Sensitivity'}}</b><button class="port-series-help" :aria-label="ru?'О чувствительности':'About sensitivity'" @click="help=true">ⓘ</button><button class="port-sensitivity-value" @click="help=true">{{sensitivity}}</button></header><SettingsArtwork kind="sensitivity" :locale="locale" :active="!help" class="port-sensitivity-art"/><label class="port-slider-row"><span>{{ru?'×0,5':'×0.5'}}</span><input v-model.number="draft" type="range" :style="{'--range-fill':`${(draft-.5)/2.5*100}%`}" min="0.5" max="3" step="0.25" :disabled="saving" :aria-label="ru?'Чувствительность':'Sensitivity'" :aria-valuetext="sensitivity" @change="changeSensitivity(draft)"><span>×3</span></label></section><div class="port-setting-tiles"><template v-for="tile in tiles" :key="tile.key"><p v-if="tile.index===2" class="port-characters-heading">{{ru?'ПЕРСОНАЖИ':'CHARACTERS'}}</p><label class="port-setting-tile"><SettingsArtwork v-if="tile.index>=2&&!preferences[tile.key]" class="port-setting-art" :kind="tile.index===2?'hero-off':'enemy-off'" :locale="locale" :active="!help"/><SettingsArtwork v-else kind="atlas" class="port-setting-art port-setting-atlas" :class="{dim:!preferences[tile.key]}" :position="`${tile.index%2?91.667:8.333}% ${tile.index>=2?91.667:8.333}%`" :locale="locale" :active="!help"/><span>{{tile.label}}</span><span class="port-setting-switch" :class="{on:preferences[tile.key]}"><GameSwitch :model-value="preferences[tile.key]" :aria-label="tile.label" :disabled="saving" @update:model-value="emit('change',tile.key,$event)"/><span aria-hidden="true">{{preferences[tile.key]?(ru?'Вкл':'On'):(ru?'Выкл':'Off')}}</span></span></label></template></div><p v-if="error" class="port-error" role="alert">{{error}}</p></div><template #footer><button class="port-primary port-settings-done" @click="dialog?.requestClose()">{{ru?'Готово':'Done'}}</button></template></ParityDialog><SensitivityHelpWindow v-if="help" :locale="locale" :value="preferences.controlSensitivity" :saving="saving" :error="error" @change="changeSensitivity" @close="help=false"/></template>
